import csv
import sys
from collections import Counter


def count_nonempty(path):
    counts = Counter()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            print("CSV 文件为空")
            return
        for i, name in enumerate(header):
            counts[i] = 0
        for row in reader:
            for i, cell in enumerate(row):
                if cell.strip():
                    counts[i] += 1
    width = max(len(h) for h in header)
    for name, i in zip(header, range(len(header))):
        print(f"{name.ljust(width)}: {counts[i]}")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"用法: python {sys.argv[0]} <csv文件>")
        sys.exit(1)
    count_nonempty(sys.argv[1])
